// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { EmptyState } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Display/EmptyState)

figma.connect(EmptyState, FIGMA_NODE_URL, {
  props: {
    icon: figma.boolean('hasIcon', { true: figma.instance('icon'), false: undefined }),
    description: figma.string('description'),
  },
  example: ({ icon, description }) => (
    <EmptyState icon={icon} description={description}></EmptyState>
  ),
});
